import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import 'package:zan/Core/Resources/app_fonts.dart';import 'package:zan/Core/Utils/Extensions/localizations_extension.dart';class TitleSliverBox extends StatelessWidget {  final String title;  const TitleSliverBox({    super.key,    required this.title,  });  @override  Widget build(BuildContext context) {    return SliverToBoxAdapter(      child: Padding(        padding: EdgeInsets.only(top: 23, bottom: 16).r,        child: Row(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            Text(title, style: AppTextStyles.h6Bold),            InkWell(              onTap: () {},                child: Text(              context.appStrings.SeeAll,              style: AppTextStyles.h7Medium.copyWith(                color: AppColors.primaryColor,              ),            )),          ],        ),      ),    );  }}